(() => {
  const style=document.createElement('style');
  style.textContent=`
    .visitor-hub{padding:74px 0;background:var(--forest);color:#f7f3ea}.hub-brand{display:flex;align-items:center;gap:10px;margin-bottom:22px}.hub-brand img{width:42px;height:42px;object-fit:cover;border-radius:9px}.hub-brand strong{font-size:21px}.hub-intro{max-width:760px;margin-bottom:28px}.hub-intro h2{margin:5px 0}.hub-intro p{color:#d4e0d4;margin:0}.hub-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px;align-items:start}.hub-card{background:var(--white);color:var(--ink);border:1px solid var(--line);border-radius:18px;padding:23px}.hub-card h3{font-size:25px;margin:0 0 6px}.hub-card>.muted{margin-top:0}.feature-grid{display:grid;grid-template-columns:1fr 1fr;gap:11px;margin-top:17px}.feature-grid input,.feature-grid select,.feature-grid textarea{font:inherit;padding:11px;border:1px solid var(--line);border-radius:9px;background:var(--cream);color:var(--ink)}.feature-grid textarea{grid-column:1/-1;min-height:92px}.feature-grid button{grid-column:1/-1}.review-card{padding:13px;border-left:3px solid var(--accent);margin:12px 0;background:var(--sand);border-radius:5px}.stars{color:#ae7d28;letter-spacing:2px}.review-scroll{max-height:260px;overflow:auto;padding-right:5px}@media(max-width:760px){.hub-grid,.feature-grid{grid-template-columns:1fr}.feature-grid textarea{grid-column:auto}.visitor-hub{padding:52px 0}}`;
  document.head.append(style);
  const footer=document.querySelector('footer'),section=document.createElement('section');
  section.className='visitor-hub';
  section.innerHTML=`<div class="shell"><div class="hub-brand"><img src="/assets/logo-fundo-el-grillo.png" alt="Fundo El Grillo"><strong>Fundo El Grillo</strong></div><div class="hub-intro"><div class="eyebrow" style="color:#d5e4b8">Planifica y comparte</div><h2>Tu próxima visita comienza aquí</h2><p>Consulta fechas para una cabaña o salón y comparte tu experiencia con otras familias.</p></div><div class="hub-grid"><article class="hub-card"><h3>Consulta disponibilidad</h3><p class="muted">Envía una solicitud y el equipo confirmará condiciones y horarios.</p><form id="bookingForm" class="feature-grid"><select name="resource_name" required><option value="">Cabaña o salón</option><option>Salón Darwin</option><option>Salón Orgánico</option><option>Quincho Club House</option><option>Cabaña Boldo</option><option>Casa Arrayán</option><option>Casa de Barro</option><option>Cabaña Ecológica</option></select><input name="guests" type="number" min="1" placeholder="Personas"><input name="start_date" type="date" required><input name="end_date" type="date" required><input name="full_name" placeholder="Nombre y apellido" required><input name="phone" type="tel" placeholder="Celular" required><textarea name="notes" placeholder="Cuéntanos qué estás buscando"></textarea><button class="btn btn-primary">Enviar consulta</button></form><p id="bookingMsg" class="muted"></p></article><article class="hub-card"><h3>Comparte tu opinión</h3><p class="muted">Las opiniones se revisan antes de aparecer publicadas.</p><form id="reviewForm" class="feature-grid"><input name="full_name" placeholder="Tu nombre" required><select name="rating" required><option value="">Calificación</option><option value="5">★★★★★ · Excelente</option><option value="4">★★★★ · Muy bueno</option><option value="3">★★★ · Bueno</option><option value="2">★★ · Regular</option><option value="1">★ · Malo</option></select><textarea name="comment" placeholder="Cuéntanos tu experiencia" required></textarea><button class="btn btn-primary">Enviar opinión</button></form><p id="reviewMsg" class="muted"></p><div id="reviews" class="review-scroll"></div></article></div></div>`;
  footer.before(section);
  const resourceSelect=document.querySelector('#bookingForm select[name="resource_name"]');
  if(resourceSelect){['Boldo','Capilla','Casa Arrayán','Casa de Barro','Casa del Cerro','Chincol','Colibrí','Ecológica','Honey Moon','Iglesia 1','Iglesia 2','Loica','Monasterio','Naranjal 1','Naranjal 2','Orgánica 1','Orgánica 2','Patagua 1','Patagua 2','Quebracho','Rapanui','Torcaza','Voluntarios'].forEach(x=>{const o=document.createElement('option');o.textContent=x;resourceSelect.append(o)})}
  const api=async(u,o)=>{const r=await fetch(u,o);const text=await r.text();let d={};try{d=JSON.parse(text)}catch{throw Error('El servidor no respondió correctamente. La solicitud puede haberse guardado; revisa el panel.')}if(!r.ok)throw Error(d.error||'No se pudo enviar');return d};
  document.getElementById('bookingForm').onsubmit=async e=>{e.preventDefault();try{await api('/api/bookings',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});e.target.reset();bookingMsg.textContent='Solicitud enviada. Te contactaremos para confirmar disponibilidad.'}catch(x){bookingMsg.textContent=x.message}};
  document.getElementById('reviewForm').onsubmit=async e=>{e.preventDefault();try{await api('/api/reviews',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});e.target.reset();reviewMsg.textContent='Gracias. Tu opinión quedará visible tras la revisión del equipo.'}catch(x){reviewMsg.textContent=x.message}};
  api('/api/reviews').then(d=>reviews.innerHTML=d.reviews.map(r=>`<div class="review-card"><div class="stars">${'★'.repeat(r.rating)}${'☆'.repeat(5-r.rating)}</div><b>${r.full_name}</b><p>${r.comment}</p></div>`).join('')).catch(()=>{});
})();
